var ENT=[["Loader", "Signature Loader pillar of the Structured Output Enforcer framework."], ["Quantizer", "Signature Quantizer pillar of the Structured Output Enforcer framework."], ["Router", "Signature Router pillar of the Structured Output Enforcer framework."], ["Streamer", "Signature Streamer pillar of the Structured Output Enforcer framework."], ["Budgeter", "Signature Budgeter pillar of the Structured Output Enforcer framework."], ["Validator", "Signature Validator pillar of the Structured Output Enforcer framework."], ["Harness", "Signature Harness pillar of the Structured Output Enforcer framework."]];
var TECH=[["Model quantization", "Reducing weight precision to fit bigger models on smaller hardware."], ["Prompt engineering", "Designing instructions, examples and formats that steer model behavior."], ["Tool-use loops", "Models emitting structured calls that code executes, then reading results back."], ["Streaming inference", "Token-by-token generation for responsive user interfaces."], ["Context management", "Budgeting prompt, history and retrieved content inside finite context windows."], ["Model routing", "Sending each request to the cheapest model capable of handling it."], ["Fallback chains", "Retrying with stronger models or providers when the first fails."], ["Output validation", "Schema-checking model JSON before trusting it downstream."], ["Embedding pipelines", "Precomputing vector representations for search and clustering."], ["Eval harnesses", "Regression suites measuring model quality on fixed task sets."]];
